#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(transparent)]
pub(crate) struct FloatOutBoyConfigImage(CustomConfigImage<FLOAT_OUT_BOY_CONFIG_LEN>);

impl Default for FloatOutBoyConfigImage {
    fn default() -> Self {
        Self::defaults()
    }
}

impl core::ops::Deref for FloatOutBoyConfigImage {
    type Target = CustomConfigImage<FLOAT_OUT_BOY_CONFIG_LEN>;

    fn deref(&self) -> &Self::Target {
        &self.0
    }
}

impl FloatOutBoyConfigImage {
    generated_image_config_fields! {
        ATR_FILTER_FIELD: CustomConfigFrequencyField => motor_current_filter_frequency -> vescpkg_rs::Frequency, offset: 165, scale: 100.0;
        DUTY_PUSHBACK_ANGLE_FIELD: CustomConfigAngleField => duty_pushback_angle -> AngleDegrees, offset: 44, scale: 100.0;
        DUTY_PUSHBACK_SPEED_FIELD: CustomConfigAngularVelocityField => duty_pushback_speed -> AngularVelocity, offset: 46, scale: 100.0;
        DUTY_PUSHBACK_THRESHOLD_FIELD: CustomConfigRatioField => duty_pushback_threshold -> Ratio, offset: 48, scale: 1000.0;
        DUTY_BEEP_ENABLED_FIELD: CustomConfigFlagField => duty_beep_enabled -> bool, offset: 50;
        FOOT_BEEP_ENABLED_FIELD: CustomConfigFlagField => foot_beep_enabled -> bool, offset: 28;
        TILTBACK_RETURN_SPEED_FIELD: CustomConfigAngularVelocityField => tiltback_return_speed -> AngularVelocity, offset: 64, scale: 100.0;
        PERSISTENT_FATAL_ERROR_FIELD: CustomConfigFlagField => persistent_fatal_error -> bool, offset: 66;
        TILTBACK_CONSTANT_ANGLE_FIELD: CustomConfigAngleField => tiltback_constant -> AngleDegrees, offset: 67, scale: 1000.0;
        TILTBACK_CONSTANT_ERPM_FIELD: CustomConfigElectricalSpeedField => tiltback_constant_erpm -> ElectricalSpeed, offset: 69;
        TILTBACK_VARIABLE_RATE_FIELD: CustomConfigPidScaleField => tiltback_variable -> PidScale, offset: 71, scale: 1000.0;
        TILTBACK_VARIABLE_MAX_FIELD: CustomConfigAngleField => tiltback_variable_max -> AngleDegrees, offset: 73, scale: 100.0;
        TILTBACK_VARIABLE_ERPM_FIELD: CustomConfigElectricalSpeedField => tiltback_variable_erpm -> ElectricalSpeed, offset: 75;
        NOSE_ANGLING_SPEED_FIELD: CustomConfigAngularVelocityField => nose_angling_speed -> AngularVelocity, offset: 77, scale: 100.0;
        INPUT_TILT_ANGLE_LIMIT_FIELD: CustomConfigAngleField => input_tilt_angle_limit -> AngleDegrees, offset: 80, scale: 100.0;
        INPUT_TILT_SPEED_FIELD: CustomConfigAngularVelocityField => input_tilt_speed -> AngularVelocity, offset: 82, scale: 100.0;
        HIGH_VOLTAGE_PUSHBACK_ANGLE_FIELD: CustomConfigAngleField => high_voltage_pushback_angle -> AngleDegrees, offset: 51, scale: 100.0;
        HIGH_VOLTAGE_THRESHOLD_FIELD: CustomConfigScaledVoltageField => high_voltage_threshold -> Voltage, offset: 55, scale: 100.0;
        LOW_VOLTAGE_PUSHBACK_ANGLE_FIELD: CustomConfigAngleField => low_voltage_pushback_angle -> AngleDegrees, offset: 57, scale: 100.0;
        LOW_VOLTAGE_THRESHOLD_FIELD: CustomConfigScaledVoltageField => low_voltage_threshold -> Voltage, offset: 61, scale: 100.0;
        BEEPER_ENABLED_FIELD: CustomConfigFlagField => beeper_enabled -> bool, offset: 242;
        LEDS_ON_FIELD: CustomConfigFlagField => leds_enabled -> bool, offset: 175;
        LEDS_HEADLIGHTS_ON_FIELD: CustomConfigFlagField => headlights_enabled -> bool, offset: 176;
    }
    #[cfg(test)]
    const LEDS_LIGHTS_OFF_WHEN_LIFTED_FIELD: CustomConfigFlagField = vescpkg_rs::generated_custom_config_field!(CustomConfigFlagField, len: FLOAT_OUT_BOY_CONFIG_LEN, offset: 179);
    #[cfg(test)]
    pub(crate) fn lights_off_when_lifted(&self) -> bool {
        generated_field(Self::LEDS_LIGHTS_OFF_WHEN_LIFTED_FIELD.read(self))
    }
    const INPUT_TILT_REMOTE_TYPE_FIELD: CustomConfigWireByteField = vescpkg_rs::generated_custom_config_field!(CustomConfigWireByteField, len: FLOAT_OUT_BOY_CONFIG_LEN, offset: 79);
    const INPUT_TILT_INVERT_FIELD: CustomConfigFlagField = vescpkg_rs::generated_custom_config_field!(CustomConfigFlagField, len: FLOAT_OUT_BOY_CONFIG_LEN, offset: 84);
    const INPUT_TILT_DEADBAND_FIELD: CustomConfigRatioField = vescpkg_rs::generated_custom_config_field!(CustomConfigRatioField, len: FLOAT_OUT_BOY_CONFIG_LEN, offset: 85, scale: 10000.0);
    const SPEED_PUSHBACK_THRESHOLD_FIELD: CustomConfigWireByteField = vescpkg_rs::generated_custom_config_field!(CustomConfigWireByteField, len: FLOAT_OUT_BOY_CONFIG_LEN, offset: 63);
    // Generated `is_beeper_enabled` follows the 18-byte hardware LED block
    // beginning at offset 224; upstream serializes it immediately before
    // `disabled` at offset 243 (`third_party/float-out-boy/src/conf/settings.xml:4049-4064`).

    // Generated `hardware.leds.mode` follows the 52-byte `leds` block beginning
    // at offset 175 in Refloat v1.2.1's generated `confparser.c`.
    const HARDWARE_LED_MODE_FIELD: CustomConfigEnumField<FloatOutBoyHardwareLedMode> = vescpkg_rs::generated_custom_config_field!(
        CustomConfigEnumField<FloatOutBoyHardwareLedMode>,
        len: FLOAT_OUT_BOY_CONFIG_LEN,
        offset: 227
    );
    // These fields immediately follow `braketilt_lingering` in the generated
    // `SerOrder` at `third_party/float-out-boy/src/conf/settings.xml:4134-4140`.
    // The generated default image confirms the bytes at 175, 176, and 179 as
    // the default-on LEDs/headlights and lifted-lights flags.
    pub(crate) const fn defaults() -> Self {
        Self(CustomConfigImage::new(FLOAT_OUT_BOY_DEFAULT_CONFIG))
    }

    pub(crate) fn from_serialized(bytes: &[u8]) -> Option<Self> {
        // C map: `read_cfg_from_eeprom` and `set_cfg` both accept only
        // successfully deserialized Float Out Boy config images at
        // `third_party/float-out-boy/src/main.c:1178-1185` and
        // `third_party/float-out-boy/src/main.c:2368-2386`.
        let bytes = <&[u8; FLOAT_OUT_BOY_CONFIG_LEN]>::try_from(bytes).ok()?;
        if !bytes.starts_with(&FLOAT_OUT_BOY_CONFIG_SIGNATURE_BYTES) {
            return None;
        }
        Self::has_valid_semantics(bytes).then(|| Self(CustomConfigImage::new(*bytes)))
    }

    fn has_valid_semantics(bytes: &[u8; FLOAT_OUT_BOY_CONFIG_LEN]) -> bool {
        let sample_rate = u16::from_be_bytes([bytes[18], bytes[19]]);
        (50..=4_000).contains(&sample_rate)
            && u16::from_be_bytes([bytes[85], bytes[86]]) < 10_000
            && bytes[79] <= 2
            && bytes[101] <= 2
            && FloatOutBoyLedConfigDecoder::new(bytes).validate().is_some()
            && u16::from_be_bytes([bytes[142], bytes[143]]) > 0
            && bytes[144] > 0
            && u16::from_be_bytes([bytes[244], bytes[245]]) > 0
            && u16::from_be_bytes([bytes[248], bytes[249]]) > 0
            && u16::from_be_bytes([bytes[252], bytes[253]]) > 0
    }

    pub(crate) const fn as_bytes(&self) -> &[u8; FLOAT_OUT_BOY_CONFIG_LEN] {
        self.0.as_bytes()
    }

    pub(crate) fn reset_tune_defaults(&mut self) {
        let mut bytes = *self.as_bytes();
        for (index, (byte, default)) in bytes
            .iter_mut()
            .zip(FLOAT_OUT_BOY_DEFAULT_CONFIG.iter())
            .enumerate()
        {
            if is_tune_default_byte(index) {
                *byte = *default;
            }
        }
        self.0 = CustomConfigImage::new(bytes);
    }

    pub(crate) fn hardware_led_mode_id(&self) -> u8 {
        Self::HARDWARE_LED_MODE_FIELD
            .read(&self.0)
            .map_or(0, WireByte::as_u8)
    }

    pub(crate) fn led_configs(
        &self,
    ) -> Option<(FloatOutBoyHardwareLedsConfig, FloatOutBoyLedsConfig)> {
        FloatOutBoyLedConfigDecoder::new(self.as_bytes()).decode()
    }

    config_views! {
        balance => FloatOutBoyBalanceConfig;
        filter => FloatOutBoyFilterConfig;
        faults => FloatOutBoyFaultConfig;
        startup => FloatOutBoyStartupConfig;
        remote_throttle => FloatOutBoyRemoteThrottleConfig;
        motor_control => FloatOutBoyMotorControlConfig;
        metadata => FloatOutBoyMetadataConfig;
    }

    config_views! {
        bms => FloatOutBoyBmsConfig;
        haptic => FloatOutBoyHapticConfig;
    }

    #[cfg(test)]
    pub(crate) fn set_haptic_current_threshold(&mut self, threshold: Ratio) -> bool {
        let mut editor = self.editor();
        FloatOutBoyHapticConfig::CURRENT_THRESHOLD_FIELD
            .write(&mut editor, threshold)
            .is_some()
    }

    pub(crate) fn balance_loop_config(&self) -> LoopConfig {
        // C map: `configure(d)` consumes these generated `float_conf` fields to
        // drive the control loop and timing at `third_party/float-out-boy/src/main.c:161-199`;
        // the serialized field order is pinned in `third_party/float-out-boy/src/conf/settings.xml:3917-3981`.
        let balance = self.balance();
        LoopConfig {
            kp: balance.kp(),
            kp2: balance.kp2(),
            ki: balance.ki(),
            kp_brake: balance.kp_brake(),
            kp2_brake: balance.kp2_brake(),
            ki_limit: balance.ki_limit(),
            booster_angle: balance.booster_angle(),
            booster_ramp: balance.booster_ramp(),
            booster_current: balance.booster_current(),
            brkbooster_angle: balance.brake_booster_angle(),
            brkbooster_ramp: balance.brake_booster_ramp(),
            brkbooster_current: balance.brake_booster_current(),
            hertz: self.startup().sample_rate(),
        }
    }

    pub(crate) fn speed_pushback_threshold(&self) -> Speed {
        generated_field(Self::SPEED_PUSHBACK_THRESHOLD_FIELD.read(self)).scaled(
            1.0,
            0.0,
            Speed::from_kilometers_per_hour,
        )
    }

    pub(crate) fn input_tilt_remote_type(&self) -> u8 {
        generated_field(Self::INPUT_TILT_REMOTE_TYPE_FIELD.read(self)).as_u8()
    }

    pub(crate) fn input_tilt_inverted(&self) -> bool {
        generated_field(Self::INPUT_TILT_INVERT_FIELD.read(self))
    }

    pub(crate) fn input_tilt_deadband(&self) -> Ratio {
        generated_field(Self::INPUT_TILT_DEADBAND_FIELD.read(self))
    }

    pub(crate) fn editor(&mut self) -> FloatOutBoyConfigEditor<'_> {
        FloatOutBoyConfigEditor(self.0.editor())
    }
}

